from bisect import bisect_left
from typing import List
DEBUG = False

class Solution:
    def subarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        endOf = [0] * n # for debug
        endOfGroup = {}
        
        sum = 0
        for i in range(n):
            sum += nums[i]
            endOf[i] = sum

            endOfGroup.setdefault(sum, [])
            endOfGroup[sum].append(i)

        groupKeys = list(endOfGroup.keys())
        groupKeys.sort()

        if DEBUG:
            print(f"nums={nums} k={k}")
            print(f"    endOf={endOf}")
            print(f"    endOfGroup={endOfGroup}")
            print(f"    groupKeys={groupKeys}")

        def findGroupKey(keyVal):
            lo = 0
            hi = len(groupKeys)-1
            if DEBUG:
                print(f"    find group key by val={keyVal} lo={lo} hi={hi}")
            # find max index such that groupKeys[index] <= keyVal
            index = -1
            while lo <= hi:
                mid = (lo + hi) // 2
                midVal = groupKeys[mid]
                if DEBUG:
                    print(f"            mid={mid} midVal={midVal}")
                if midVal <= keyVal:
                    index = max(index, mid)
                    lo = mid + 1
                else:
                    hi = mid - 1
            if DEBUG:
                print(f"        index of group key {keyVal}={index}")    

            if index >= 0 and groupKeys[index] != keyVal:
                index = -1

            return index    


        result = 0
        prevEndOf = 0 # logical endOf[-1]
        for i in range(n):
            # looking for sub string that starts from index i and whose sum is k
            # sum of a sub string starting from index i = endOf[x] - endOf[i-1], where x >= i. 
            # endOf[x] - endOf[i-1]=k => endOf[x] = endOf[i-1]+k
            grpKeyIdx = findGroupKey(k+prevEndOf)
            if grpKeyIdx >= 0:
                # endOfGroup[*] is sorted j; count of j >= i via binary search
                ends = endOfGroup[groupKeys[grpKeyIdx]]
                result += len(ends) - bisect_left(ends, i)
            prevEndOf = endOf[i]            

        return result

